package edu.pe.cibertec.saibm.membresia.infrastructure.in.rest;
import java.time.Instant; import java.util.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import edu.pe.cibertec.saibm.membresia.application.port.in.MembershipUseCase;
@RestController @RequestMapping("/api/v1/memberships") public class MembershipController {private final MembershipUseCase use;private final TransitionalWriteAuthorizer auth;public MembershipController(MembershipUseCase u,TransitionalWriteAuthorizer a){use=u;auth=a;}@GetMapping("/plans") List<MembershipUseCase.PlanView> plans(){return use.activePlans(Instant.now());}@GetMapping("/plans/{id}") MembershipUseCase.PlanView plan(@PathVariable UUID id){return use.plan(id);}@PostMapping("/plans")@ResponseStatus(HttpStatus.CREATED) MembershipUseCase.PlanView create(@Valid @RequestBody PlanRequest r,HttpServletRequest h){auth.require(h);return use.createPlan(new MembershipUseCase.PlanCommand(r.code(),r.name(),r.reservationLimit(),r.validFrom(),r.validUntil()));}@PutMapping("/plans/{id}") MembershipUseCase.PlanView update(@PathVariable UUID id,@Valid @RequestBody PlanRequest r,HttpServletRequest h){auth.require(h);return use.updatePlan(id,new MembershipUseCase.PlanCommand(r.code(),r.name(),r.reservationLimit(),r.validFrom(),r.validUntil()));}@DeleteMapping("/plans/{id}")@ResponseStatus(HttpStatus.NO_CONTENT) void deactivate(@PathVariable UUID id,HttpServletRequest h){auth.require(h);use.deactivatePlan(id);}@PostMapping("/assignments") MembershipUseCase.AssignmentView assign(@RequestHeader("Idempotency-Key")String key,@RequestHeader(value="X-Correlation-Id",defaultValue="")String c,@Valid @RequestBody AssignmentRequest r,HttpServletRequest h){auth.require(h);return use.assign(new MembershipUseCase.AssignmentCommand(r.userId(),r.planId(),r.validFrom()==null?Instant.now():r.validFrom(),r.validUntil()),key,c);}@GetMapping("/entitlements/{userId}") MembershipUseCase.EntitlementView entitlement(@PathVariable String userId){return use.entitlement(userId,Instant.now());}@GetMapping("/history/{userId}") List<?> history(@PathVariable String userId){return use.history(userId);}record PlanRequest(@NotBlank String code,@NotBlank String name,@Min(0)int reservationLimit,@NotNull Instant validFrom,Instant validUntil){}record AssignmentRequest(@NotBlank String userId,@NotNull UUID planId,Instant validFrom,Instant validUntil){}}
